from pathlib import Path
import hashlib,json
p=Path(__file__).resolve().parent
prompt='''Edit IMAGE 1 as the exact target: James engineer upper-body crop, left-facing THREE-QUARTER view, finely painted game sprite. Image 2 shows his preceding PROFILE-LEFT pose and is only a directional reference. Create ONE late in-between pose: keep image 1's three-quarter-left orientation, but rotate the face, neck/collar and near shoulder together a VERY SMALL amount (about 3 degrees) toward the profile-left direction of image 2. The result is about 80 percent of the transition from image 2 to image 1. Do NOT revert to full profile. Keep both eye/cheek hints and the outgoing master nose/moustache identity; the rotation is tiny. NO nod, head translation, height/size change or floating head splice. Shoulder and collar articulate naturally with the head. Keep crown position, same fixed square framing and complete original margins. Keep backpack attached, unchanged engineering patch/symbol, goggles, hairstyle, identity, hand locations, body proportions and native fine painted detail density. Do not enlarge face, shoulder or badge, sharpen into a new character or invent insignia.

Match image 1 EXACTLY in subdued MATTE material and colour: neutral charcoal/graphite cloth, grey-brown hair, muted ochre engineering patches, subdued warm natural skin, worn grey metal. No purple/magenta tint, orange skin, glossy highlights, exposure lift, expanded black shadows or light outlines. GENUINELY TRANSPARENT background with clean antialiased silhouette edges, preserving real grey hair and silver cuffs. No checkerboard pixels, drop shadow, halo, text, border, full body extension or zoom. One registered upper-body pose ONLY, complete original square canvas. Preserve image 1 target composition; image 2 must not pull the pose back into profile or move it.'''
(p/'late-prompt.txt').write_text(prompt+'\n',encoding='utf-8')
names=['last-input.png','first-input.png','late-prompt.txt']
(p/'late-inputs.json').write_text(json.dumps({'target':'last-input.png','directionReference':'first-input.png','preCallSha256':{n:hashlib.sha256((p/n).read_bytes()).hexdigest() for n in names},'selected':False},indent=2)+'\n',encoding='utf-8')
print('Exact outgoing-target late-pose prompt and two input hashes frozen.')
